import java.util.*;

class Solution {
    static Map<String, List<String>> invertIndex(Map<String, List<String>> accountTags) {
        Map<String, TreeSet<String>> index = new HashMap<>();
        for (Map.Entry<String, List<String>> entry : accountTags.entrySet()) {
            for (String tag : entry.getValue()) {
                index.computeIfAbsent(tag, t -> new TreeSet<>()).add(entry.getKey());
            }
        }
        Map<String, List<String>> result = new HashMap<>();
        index.forEach((tag, accounts) -> result.put(tag, new ArrayList<>(accounts)));
        return result;
    }
}
